from abc import ABC, abstractmethod

class Empleado(ABC):
    @abstractmethod
    def salario(self):
        pass

class Vendedor(Empleado):
    def salario(self):
        return 2000

try:
    Empleado()
except TypeError as e:
    print("Error:", e)

v = Vendedor()
print(v.salario())
